import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import { Game } from './game/engine';
import type { DockData, HudData, MsgKind, Summary } from './game/engine';
import { loadRecords } from './game/economy';
import type { DiffId, UpgId } from './game/economy';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import StationPanel from './components/StationPanel';
import { GameOverScreen, Menu, PauseScreen } from './components/Screens';
type Screen = 'menu' | 'play' | 'paused' | 'docked' | 'over';
const PREFS_KEY = 'galaxia-prefs';

function loadPrefs(): { diff: DiffId; muted: boolean } {
  try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}'); return { diff: p.diff || 'normal', muted: !!p.muted }; }
  catch { return { diff: 'normal', muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const timers = useRef<number[]>([]);
  const msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [dock, setDock] = useState<DockData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));
  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.slice(-4), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), kind === 'big' ? 3200 : 2200));
  }, []);
  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); setScreen('paused'); }
    else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
  }, []);
  const doDock = useCallback(() => { gameRef.current?.tryDock(); }, []);
  useEffect(() => {
    if (!wrapRef.current) return;
    const g = new Game(wrapRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onDock: () => { setDock(g.getDock()); setScreen('docked'); },
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 150, spread: 90, origin: { y: 0.35 }, colors: ['#7ff6ff', '#b98aff', '#ff7ad9', '#ffc37a'] });
      },
    });
    g.input.onPause = togglePause;
    g.input.onDock = doDock;
    g.input.onAnyKey = () => g.sfx.unlock();
    gameRef.current = g;
    return () => {
      timers.current.forEach(t => clearTimeout(t)); timers.current = [];
      g.dispose(); gameRef.current = null;
    };
  }, [pushMsg, togglePause, doDock]);
  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, muted })); } catch { /* sin almacenamiento */ }
  }, [diff, muted]);
  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null); setDock(null);
    g.setMuted(muted); g.start(diff);
    setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setScreen('menu'); setRecords(loadRecords()); };
  const station = (fn: (g: Game) => void) => { const g = gameRef.current; if (!g) return; fn(g); setDock(g.getDock()); };
  const leave = () => { gameRef.current?.undock(); setDock(null); setScreen('play'); };
  const radarRef = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.setRadar(c); }, []);
  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#05030c] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => gameRef.current?.sfx.unlock()} />
      {(screen === 'play' || screen === 'paused' || screen === 'docked') && (
        <Hud hud={hud} msgs={msgs} muted={muted} touch={touch && screen === 'play'} input={gameRef.current?.input ?? null}
          onMute={() => setMuted(m => !m)} onPause={togglePause} onDock={doDock} radarRef={radarRef} />
      )}
      {screen === 'menu' && <Menu diff={diff} setDiff={setDiff} records={records} muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />}
      {screen === 'docked' && dock && (
        <StationPanel d={dock} onSell={() => station(g => g.sellAll())} onRepair={() => station(g => g.repair())}
          onRefuel={() => station(g => g.refuel())} onBuy={(id: UpgId) => station(g => g.buy(id))} onLeave={leave} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useRef } from 'react';
import type { PointerEvent as RPointerEvent, ReactNode } from 'react';
import { Pause, Volume2, VolumeX, Shield, Fuel, Wrench, Package, Skull, Coins, Zap, Anchor } from 'lucide-react';
import type { HudData } from '../game/engine';
import type { Input } from '../game/input';
import { ORES } from '../game/economy';

export interface Msg { id: number; text: string; kind: 'big' | 'good' | 'warn' | 'info' }

function Bar({ icon, label, v, max, color }: { icon: ReactNode; label: string; v: number; max: number; color: string }) {
  const p = Math.max(0, Math.min(1, v / max));
  const low = p < 0.25;
  return (
    <div className="flex items-center gap-2">
      <div className={low ? 'text-red-400 gx-pulse' : 'text-cyan-200'}>{icon}</div>
      <div className="w-28 sm:w-40">
        <div className="flex justify-between text-[10px] uppercase tracking-widest text-cyan-100/70"><span>{label}</span><span className="gx-mono">{Math.ceil(v)}</span></div>
        <div className="h-2 rounded-full bg-white/10 overflow-hidden">
          <div className="h-full rounded-full transition-all duration-150" style={{ width: `${p * 100}%`, background: low ? '#f87171' : color, boxShadow: `0 0 10px ${color}` }} />
        </div>
      </div>
    </div>
  );
}

function Joystick({ input }: { input: Input }) {
  const base = useRef<HTMLDivElement>(null); const knob = useRef<HTMLDivElement>(null);
  const move = (e: RPointerEvent<HTMLDivElement>) => {
    const b = base.current!.getBoundingClientRect();
    let x = (e.clientX - (b.left + b.width / 2)) / (b.width / 2), y = (e.clientY - (b.top + b.height / 2)) / (b.height / 2);
    const l = Math.hypot(x, y); if (l > 1) { x /= l; y /= l; }
    input.touch.x = x; input.touch.y = y; input.touch.active = true;
    if (knob.current) knob.current.style.transform = `translate(${x * 34}px, ${y * 34}px)`;
  };
  const end = () => { input.touch.x = 0; input.touch.y = 0; input.touch.active = false; if (knob.current) knob.current.style.transform = ''; };
  return (
    <div ref={base} className="absolute left-5 bottom-5 w-32 h-32 rounded-full border border-cyan-300/40 bg-cyan-400/10 pointer-events-auto touch-none flex items-center justify-center"
      onPointerDown={e => { (e.target as HTMLElement).setPointerCapture(e.pointerId); move(e); }} onPointerMove={e => e.buttons && move(e)} onPointerUp={end} onPointerCancel={end}>
      <div ref={knob} className="w-14 h-14 rounded-full bg-cyan-300/50 border border-white/50 shadow-[0_0_20px_rgba(127,246,255,0.6)]" />
    </div>
  );
}

function TouchBtn({ label, onDown, onUp, className }: { label: string; onDown: () => void; onUp: () => void; className: string }) {
  return (
    <button className={`rounded-full font-bold text-white text-xs uppercase tracking-wider pointer-events-auto touch-none select-none border border-white/30 ${className}`}
      onPointerDown={e => { e.preventDefault(); onDown(); }} onPointerUp={onUp} onPointerLeave={onUp} onPointerCancel={onUp}>{label}</button>
  );
}

export default function Hud({ hud, msgs, muted, touch, input, onMute, onPause, onDock, radarRef }: {
  hud: HudData | null; msgs: Msg[]; muted: boolean; touch: boolean; input: Input | null;
  onMute: () => void; onPause: () => void; onDock: () => void; radarRef: (c: HTMLCanvasElement | null) => void;
}) {
  const used = hud ? hud.cargo.reduce((a, b) => a + b, 0) : 0;
  return (
    <div className="absolute inset-0 pointer-events-none gx-font text-white">
      {/* Recursos */}
      <div className="absolute top-3 left-3 gx-panel rounded-xl px-3 py-2 flex flex-col gap-1.5">
        {hud && <>
          <Bar icon={<Wrench size={16} />} label="Casco" v={hud.hull} max={hud.maxHull} color="#5aff8a" />
          <Bar icon={<Shield size={16} />} label="Escudo" v={hud.shield} max={hud.maxShield} color="#4fd8ff" />
          <Bar icon={<Fuel size={16} />} label="Combustible" v={hud.fuel} max={hud.maxFuel} color="#ffd23a" />
        </>}
      </div>
      {/* Créditos y amenaza */}
      <div className="absolute top-3 left-1/2 -translate-x-1/2 gx-panel rounded-xl px-4 py-1.5 flex items-center gap-4 text-sm">
        <span className="flex items-center gap-1.5 text-amber-300"><Coins size={16} /><b className="gx-mono">{hud ? hud.credits : 0}</b> ₵</span>
        <span className="flex items-center gap-1.5 text-fuchsia-300"><Skull size={16} />Amenaza <b className="gx-mono">{hud ? hud.threat : 1}</b></span>
        <span className="hidden sm:flex items-center gap-1.5 text-cyan-200">Puntos <b className="gx-mono">{hud ? hud.score : 0}</b></span>
      </div>
      {/* Botones */}
      <div className="absolute top-3 right-3 flex gap-2 pointer-events-auto">
        <button onClick={onMute} className="gx-panel rounded-lg p-2 hover:bg-white/10" aria-label="Silencio">{muted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
        <button onClick={onPause} className="gx-panel rounded-lg p-2 hover:bg-white/10" aria-label="Pausa"><Pause size={18} /></button>
      </div>
      {/* Radar + bodega */}
      <div className={`absolute right-3 ${touch ? 'top-16' : 'bottom-3'} flex flex-col items-end gap-2`}>
        <canvas ref={radarRef} className="w-36 h-36 sm:w-44 sm:h-44 rounded-full" />
        {hud && (
          <div className="gx-panel rounded-xl px-3 py-1.5 text-xs flex items-center gap-2">
            <Package size={14} className={used >= hud.cargoCap ? 'text-red-400' : 'text-cyan-200'} />
            <span className="gx-mono">{used}/{hud.cargoCap}</span>
            {ORES.map((o, i) => <span key={o.name} className="gx-mono" style={{ color: o.css }}>◆{hud.cargo[i]}</span>)}
          </div>
        )}
      </div>
      {/* Velocímetro e indicadores */}
      {hud && (
        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex flex-col items-center gap-1">
          {hud.doubleT > 0 && <div className="text-pink-300 text-xs flex items-center gap-1"><Zap size={14} />Láser doble {Math.ceil(hud.doubleT)}s</div>}
          {hud.dockable && (
            <button onClick={onDock} className="pointer-events-auto gx-panel gx-pulse rounded-full px-4 py-1.5 text-sm text-cyan-200 flex items-center gap-2">
              <Anchor size={16} />{touch ? 'Toca para atracar' : 'Pulsa E para atracar'}
            </button>
          )}
          <div className="gx-panel rounded-xl px-4 py-1 flex items-baseline gap-3">
            <span className="gx-mono text-2xl font-bold text-cyan-100">{Math.round(hud.speed * 10)}</span>
            <span className="text-[10px] uppercase tracking-widest text-cyan-200/70">m/s {hud.boosting ? '· turbo' : ''}</span>
            <span className="text-[10px] uppercase tracking-widest text-cyan-200/70">Estación <b className="gx-mono">{Math.round(hud.stationDist * 10)}</b> m</span>
            {hud.pirates > 0 && <span className="text-[10px] uppercase tracking-widest text-red-300">Piratas {hud.pirates}</span>}
          </div>
        </div>
      )}
      {/* Mensajes */}
      <div className="absolute top-20 left-1/2 -translate-x-1/2 flex flex-col items-center gap-1.5 w-[90%]">
        {msgs.map(m => (
          <div key={m.id} className={`gx-in text-center font-semibold drop-shadow-[0_0_10px_rgba(0,0,0,0.9)] ${m.kind === 'big' ? 'text-2xl sm:text-3xl gx-title' : m.kind === 'warn' ? 'text-lg text-red-300' : m.kind === 'good' ? 'text-base text-emerald-300' : 'text-base text-cyan-100'}`}>{m.text}</div>
        ))}
      </div>
      {touch && input && <>
        <Joystick input={input} />
        <div className="absolute right-5 bottom-6 flex flex-col items-end gap-3">
          <TouchBtn label="Turbo" className="w-16 h-16 bg-amber-500/40" onDown={() => (input.touch.boost = true)} onUp={() => (input.touch.boost = false)} />
          <TouchBtn label="Fuego" className="w-24 h-24 bg-fuchsia-500/50" onDown={() => (input.touch.fire = true)} onUp={() => (input.touch.fire = false)} />
        </div>
      </>}
    </div>
  );
}

import { Rocket, Trophy, Play, RotateCcw, Home, Volume2, VolumeX, Pickaxe, Store, Crosshair, Sparkles } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS } from '../game/economy';
import type { DiffId } from '../game/economy';
import type { Summary } from '../game/engine';
const fmtTime = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

export function Menu({ diff, setDiff, records, muted, onMute, onPlay }: {
  diff: DiffId; setDiff: (d: DiffId) => void; records: Record<DiffId, number>; muted: boolean; onMute: () => void; onPlay: () => void;
}) {
  return (
    <div className="absolute inset-0 gx-font text-white flex items-center justify-center p-4 bg-gradient-to-r from-[#05030cee] via-[#05030c88] to-transparent overflow-y-auto">
      <div className="w-full max-w-5xl flex flex-col md:flex-row gap-6 items-center md:items-stretch">
        <div className="flex-1 gx-in flex flex-col justify-center">
          <div className="flex items-center gap-2 text-cyan-300/80 text-xs uppercase tracking-[0.4em]"><Sparkles size={14} />Frontera estelar</div>
          <h1 className="gx-title text-6xl sm:text-8xl font-black tracking-tight leading-none mt-2">GALAXIA</h1>
          <p className="mt-4 text-cyan-50/80 max-w-md text-sm sm:text-base">
            Pilota tu nave entre nebulosas y planetas anillados. Mina asteroides, vende el mineral en la estación,
            mejora motor, láser y blindaje… y sobrevive a las flotas piratas que cada vez llegan en mayor número.
          </p>
          <div className="mt-5 grid grid-cols-3 gap-2 max-w-md text-xs">
            {[[<Pickaxe key="a" size={18} />, 'Mina', 'Hierro, cobalto y cristal'], [<Store key="b" size={18} />, 'Comercia', 'Vende y mejora la nave'], [<Crosshair key="c" size={18} />, 'Combate', 'Cazas, corsarios y élites']].map(([ic, t, d]) => (
              <div key={String(t)} className="gx-panel rounded-lg p-2.5">
                <div className="text-fuchsia-300">{ic}</div><div className="font-bold mt-1">{t}</div><div className="text-white/60">{d}</div>
              </div>
            ))}
          </div>
        </div>
        <div className="w-full md:w-96 gx-panel rounded-2xl p-5 gx-in flex flex-col gap-4">
          <div>
            <div className="text-xs uppercase tracking-widest text-cyan-200/70 mb-2">Dificultad</div>
            <div className="flex flex-col gap-2">
              {(Object.keys(DIFFS) as DiffId[]).map(id => (
                <button key={id} onClick={() => setDiff(id)}
                  className={clsx('text-left rounded-xl px-3 py-2 border transition', diff === id ? 'border-fuchsia-400 bg-fuchsia-500/20 shadow-[0_0_18px_rgba(217,70,239,0.35)]' : 'border-white/10 hover:border-white/30 bg-white/5')}>
                  <div className="flex justify-between items-center">
                    <span className="font-bold">{DIFFS[id].name}</span>
                    <span className="text-xs text-amber-300 flex items-center gap-1"><Trophy size={12} />{records[id]}</span>
                  </div>
                  <div className="text-xs text-white/60">{DIFFS[id].desc}</div>
                </button>
              ))}
            </div>
          </div>
          <div className="text-xs text-white/70 leading-relaxed">
            <div className="uppercase tracking-widest text-cyan-200/70 mb-1">Controles</div>
            <b>↑/W</b> propulsión · <b>↓/S</b> frenar · <b>←→/A D</b> girar<br />
            <b>Espacio</b> láser · <b>Shift</b> turbo · <b>E</b> atracar · <b>P/Esc</b> pausa<br />
            En móvil: joystick y botones en pantalla.
          </div>
          <div className="flex gap-2">
            <button onClick={onPlay} className="gx-btn flex-1 rounded-xl py-3 font-black text-lg uppercase tracking-wider flex items-center justify-center gap-2">
              <Rocket size={20} />Jugar
            </button>
            <button onClick={onMute} className="gx-panel rounded-xl px-3" aria-label="Silencio">{muted ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <div className="absolute inset-0 gx-font text-white flex items-center justify-center bg-[#05030caa] backdrop-blur-sm">
      <div className="gx-panel rounded-2xl p-6 w-72 gx-in flex flex-col gap-3">
        <h2 className="gx-title text-4xl font-black text-center mb-2">PAUSA</h2>
        <button onClick={onResume} className="gx-btn rounded-xl py-2.5 font-bold flex items-center justify-center gap-2"><Play size={18} />Continuar</button>
        <button onClick={onRestart} className="rounded-xl py-2.5 font-bold bg-white/10 hover:bg-white/20 flex items-center justify-center gap-2"><RotateCcw size={18} />Reiniciar</button>
        <button onClick={onMenu} className="rounded-xl py-2.5 font-bold bg-white/10 hover:bg-white/20 flex items-center justify-center gap-2"><Home size={18} />Menú</button>
      </div>
    </div>
  );
}

export function GameOverScreen({ s, onRetry, onMenu }: { s: Summary; onRetry: () => void; onMenu: () => void }) {
  const rows: [string, string][] = [
    ['Créditos ganados', String(s.score)], ['Piratas destruidos', String(s.kills)], ['Mineral extraído', String(s.ore)],
    ['Tiempo de vuelo', fmtTime(s.time)], ['Amenaza alcanzada', String(s.threat)], ['Récord (' + DIFFS[s.diff].name + ')', String(s.record)],
  ];
  return (
    <div className="absolute inset-0 gx-font text-white flex items-center justify-center bg-[#05030cbb] backdrop-blur-sm p-4">
      <div className="gx-panel rounded-2xl p-6 w-full max-w-sm gx-in">
        <h2 className="text-4xl font-black text-center text-red-300 drop-shadow-[0_0_20px_rgba(255,80,80,0.6)]">NAVE PERDIDA</h2>
        {s.newRecord && <div className="mt-2 text-center gx-title text-xl font-black gx-pulse">¡Nuevo récord!</div>}
        <div className="mt-4 text-center"><span className="text-xs uppercase tracking-widest text-white/60">Puntuación</span>
          <div className="gx-mono text-5xl font-black text-amber-300">{s.score}</div></div>
        <div className="mt-4 grid grid-cols-2 gap-2 text-sm">
          {rows.map(([k, v]) => <div key={k} className="bg-white/5 rounded-lg px-3 py-2"><div className="text-[10px] uppercase text-white/50">{k}</div><div className="gx-mono font-bold">{v}</div></div>)}
        </div>
        <div className="mt-5 flex gap-2">
          <button onClick={onRetry} className="gx-btn flex-1 rounded-xl py-2.5 font-bold flex items-center justify-center gap-2"><RotateCcw size={18} />Reintentar</button>
          <button onClick={onMenu} className="rounded-xl px-4 font-bold bg-white/10 hover:bg-white/20 flex items-center gap-2"><Home size={18} />Menú</button>
        </div>
      </div>
    </div>
  );
}

import { Coins, Wrench, Fuel, Rocket, Zap, Shield, Package, ArrowUpCircle, Satellite } from 'lucide-react';
import type { ReactNode } from 'react';
import clsx from 'clsx';
import { ORES, UPGS } from '../game/economy';
import type { UpgId } from '../game/economy';
import type { DockData } from '../game/engine';
const UPG_ICONS: Record<UpgId, ReactNode> = { motor: <Rocket size={18} />, laser: <Zap size={18} />, casco: <Shield size={18} />, bodega: <Package size={18} /> };

export default function StationPanel({ d, onSell, onRepair, onRefuel, onBuy, onLeave }: {
  d: DockData; onSell: () => void; onRepair: () => void; onRefuel: () => void; onBuy: (id: UpgId) => void; onLeave: () => void;
}) {
  const used = d.cargo.reduce((a, b) => a + b, 0);
  return (
    <div className="absolute inset-0 gx-font text-white flex items-center justify-center bg-[#05030c99] backdrop-blur-[2px] p-3 overflow-y-auto">
      <div className="gx-panel rounded-2xl p-5 w-full max-w-3xl gx-in">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2">
            <Satellite className="text-cyan-300" />
            <div><div className="text-xs uppercase tracking-[0.3em] text-cyan-300/70">Estación orbital</div><h2 className="gx-title text-3xl font-black">ÁGORA-7</h2></div>
          </div>
          <div className="flex items-center gap-2 text-2xl text-amber-300 font-black"><Coins /><span className="gx-mono">{d.credits}</span> ₵</div>
        </div>
        <div className="mt-4 grid md:grid-cols-2 gap-4">
          <div className="bg-white/5 rounded-xl p-3">
            <div className="text-xs uppercase tracking-widest text-cyan-200/70 mb-2">Mercado · bodega {used}</div>
            {ORES.map((o, i) => (
              <div key={o.name} className="flex justify-between text-sm py-1 border-b border-white/5">
                <span style={{ color: o.css }}>◆ {o.name}</span>
                <span className="gx-mono text-white/80">{d.cargo[i]} × {o.price} ₵</span>
              </div>
            ))}
            <button onClick={onSell} disabled={!d.cargoValue}
              className={clsx('mt-3 w-full rounded-lg py-2 font-bold', d.cargoValue ? 'gx-btn' : 'bg-white/10 text-white/40')}>
              Vender todo · +{d.cargoValue} ₵
            </button>
            <div className="mt-3 grid grid-cols-2 gap-2">
              <button onClick={onRepair} disabled={d.repairCost <= 0} className="rounded-lg py-2 text-sm font-semibold bg-emerald-500/20 hover:bg-emerald-500/30 border border-emerald-400/30 disabled:opacity-40 flex flex-col items-center">
