              <button onClick={onRefuel} disabled={d.fuelCost <= 0} className="rounded-lg py-2 text-sm font-semibold bg-amber-500/20 hover:bg-amber-500/30 border border-amber-400/30 disabled:opacity-40 flex flex-col items-center">
                <span className="flex items-center gap-1"><Fuel size={14} />Repostar</span>
                <span className="gx-mono text-xs text-white/70">{Math.ceil(d.fuel)}/{d.maxFuel} · {d.fuelCost} ₵</span>
              </button>
            </div>
          </div>
          <div className="bg-white/5 rounded-xl p-3">
            <div className="text-xs uppercase tracking-widest text-cyan-200/70 mb-2">Astillero · mejoras</div>
            <div className="flex flex-col gap-2">
              {UPGS.map(u => {
                const lv = d.upgrades[u.id]; const price = u.prices[lv]; const max = price === undefined; const can = !max && d.credits >= price;
                return (
                  <div key={u.id} className="flex items-center gap-2 bg-black/20 rounded-lg p-2">
                    <div className="text-fuchsia-300">{UPG_ICONS[u.id]}</div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-bold">{u.name}</div>
                      <div className="text-[11px] text-white/55 truncate">{u.desc}</div>
                      <div className="flex gap-1 mt-1">{u.prices.map((_, i) => <div key={i} className={clsx('h-1.5 w-6 rounded-full', i < lv ? 'bg-cyan-300 shadow-[0_0_6px_#7ff6ff]' : 'bg-white/15')} />)}</div>
                    </div>
                    <button onClick={() => onBuy(u.id)} disabled={!can}
                      className={clsx('rounded-lg px-2.5 py-1.5 text-xs font-bold flex items-center gap-1', can ? 'gx-btn' : 'bg-white/10 text-white/40')}>
                      <ArrowUpCircle size={14} />{max ? 'MÁX' : `${price} ₵`}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
        <button onClick={onLeave} className="gx-btn mt-4 w-full rounded-xl py-3 font-black uppercase tracking-wider flex items-center justify-center gap-2">
          <Rocket size={18} />Despegar
        </button>
      </div>
    </div>
  );
}

import * as THREE from 'three';
import { fbm3, makeRng, rr } from './noise';
import type { Rng } from './noise';
import { ORES } from './economy';
import type { OreId } from './economy';

export interface Rock { pos: THREE.Vector3; rot: THREE.Euler; spin: THREE.Vector3; scale: THREE.Vector3; r: number; hp: number; ore: OreId; alive: boolean; respawn: number; cluster: number; hitT: number }
export interface Cluster { center: THREE.Vector3; radius: number }

const ROCK_COLORS = [0x8a7464, 0x5f6c86, 0x8a5c88];
const _m = new THREE.Matrix4(); const _q = new THREE.Quaternion(); const _c = new THREE.Color();

function rockGeometry(seed: number) {
  const g = new THREE.IcosahedronGeometry(1, 2);
  const p = g.attributes.position as THREE.BufferAttribute; const v = new THREE.Vector3();
  for (let i = 0; i < p.count; i++) {
    v.fromBufferAttribute(p, i);
    const n = fbm3(v.x * 1.6 + seed, v.y * 1.6, v.z * 1.6, 4);
    v.multiplyScalar(0.62 + n * 0.85); p.setXYZ(i, v.x, v.y, v.z);
  }
  g.computeVertexNormals();
  return g;
}

/** Campos de asteroides minables (InstancedMesh por variante de forma). */
export class AsteroidField {
  rocks: Rock[] = [];
  clusters: Cluster[] = [];
  private meshes: THREE.InstancedMesh[] = [];
  private geos: THREE.BufferGeometry[] = [];
  private mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92, metalness: 0.1, flatShading: true });
  private rng: Rng;
  constructor(private scene: THREE.Scene, seed: number) {
    this.rng = makeRng(seed * 7 + 3);
    const rng = this.rng;
    this.clusters = [
      { center: new THREE.Vector3(25, 0, -185), radius: 125 },
      { center: new THREE.Vector3(rr(rng, 500, 700), 0, rr(rng, 150, 350)), radius: 170 },
      { center: new THREE.Vector3(rr(rng, -700, -500), 0, rr(rng, -450, -250)), radius: 170 },
      { center: new THREE.Vector3(rr(rng, -300, 100), 0, rr(rng, 550, 750)), radius: 150 },
    ];
    const PER = 85;
    for (let v = 0; v < 2; v++) {
      const g = rockGeometry(v * 13.7 + seed % 50); this.geos.push(g);
      const m = new THREE.InstancedMesh(g, this.mat, (PER * this.clusters.length) / 2);
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage); m.frustumCulled = false;
      scene.add(m); this.meshes.push(m);
    }
    this.clusters.forEach((_, ci) => { for (let i = 0; i < PER; i++) this.rocks.push(this.makeRock(ci)); });
    this.rocks.forEach((r, i) => this.paint(i));
  }
  private makeRock(ci: number): Rock {
    const rock: Rock = { pos: new THREE.Vector3(), rot: new THREE.Euler(), spin: new THREE.Vector3(), scale: new THREE.Vector3(), r: 1, hp: 1, ore: 0, alive: true, respawn: 0, cluster: ci, hitT: 0 };
    this.reseed(rock); return rock;
  }
  private reseed(k: Rock) {
    const rng = this.rng; const c = this.clusters[k.cluster];
    const a = rng() * Math.PI * 2, d = Math.sqrt(rng()) * c.radius;
    k.pos.set(c.center.x + Math.cos(a) * d, rr(rng, -22, 22), c.center.z + Math.sin(a) * d);
    if (k.pos.distanceTo(new THREE.Vector3()) < 70) k.pos.z -= 80; // despeja la estación
    const big = rng() < 0.18;
    k.r = big ? rr(rng, 9, 15) : rr(rng, 2.5, 7.5);
    k.scale.set(k.r * rr(rng, 0.8, 1.2), k.r * rr(rng, 0.7, 1.1), k.r * rr(rng, 0.8, 1.25));
    k.rot.set(rng() * 6, rng() * 6, rng() * 6);
    k.spin.set(rr(rng, -0.5, 0.5), rr(rng, -0.5, 0.5), rr(rng, -0.5, 0.5));
    const t = rng(); k.ore = (t < 0.1 ? 2 : t < 0.38 ? 1 : 0) as OreId;
    k.hp = k.r * 5; k.alive = true; k.hitT = 0;
  }
  private paint(i: number) {
    const k = this.rocks[i]; const m = this.meshes[i % 2]; const idx = Math.floor(i / 2);
    const flash = k.hitT > 0 ? k.hitT * 3 : 0;
    _c.setHex(ROCK_COLORS[k.ore]).offsetHSL(0, 0, ((i * 37) % 10) / 100 - 0.05);
    _c.r += flash; _c.g += flash * 0.8; _c.b += flash * 0.6;
    m.setColorAt(idx, _c);
  }
  update(dt: number) {
    this.rocks.forEach((k, i) => {
      const m = this.meshes[i % 2]; const idx = Math.floor(i / 2);
      if (!k.alive) {
        k.respawn -= dt; if (k.respawn <= 0) this.reseed(k);
        _m.makeScale(0, 0, 0); m.setMatrixAt(idx, _m); return;
      }
      k.rot.x += k.spin.x * dt; k.rot.y += k.spin.y * dt; k.rot.z += k.spin.z * dt;
      _q.setFromEuler(k.rot); _m.compose(k.pos, _q, k.scale); m.setMatrixAt(idx, _m);
      if (k.hitT > 0) { k.hitT = Math.max(0, k.hitT - dt); this.paint(i); }
    });
    for (const m of this.meshes) { m.instanceMatrix.needsUpdate = true; if (m.instanceColor) m.instanceColor.needsUpdate = true; }
  }
  /** Devuelve la roca alcanzada por un punto (o null). */
  hit(p: THREE.Vector3, pad = 0): Rock | null {
    for (const k of this.rocks) if (k.alive && k.pos.distanceToSquared(p) < (k.r + pad) * (k.r + pad)) return k;
    return null;
  }
  /** Aplica daño; devuelve true si se destruye. */
  damage(k: Rock, dmg: number) {
    k.hp -= dmg; k.hitT = 0.25; this.paint(this.rocks.indexOf(k));
    if (k.hp > 0) return false;
    k.alive = false; k.respawn = 25 + Math.random() * 20;
    return true;
  }
  clusterOf(p: THREE.Vector3) { return this.clusters.findIndex(c => c.center.distanceTo(p) < c.radius + 40); }
  dispose() { this.meshes.forEach(m => this.scene.remove(m)); this.geos.forEach(g => g.dispose()); this.mat.dispose(); }
}

export type PowerId = 'escudo' | 'reparar' | 'combustible' | 'doble';
export const POWERS: Record<PowerId, { name: string; color: number }> = {
  escudo: { name: 'Escudo recargado', color: 0x4fd8ff }, reparar: { name: 'Nanorreparación', color: 0x5aff8a },
  combustible: { name: 'Célula de combustible', color: 0xffd23a }, doble: { name: 'Láser doble', color: 0xff5ad2 },
};
interface Item { mesh: THREE.Mesh; vel: THREE.Vector3; life: number; alive: boolean; ore: OreId; power: PowerId | null }

/** Mineral y potenciadores flotantes recogibles. */
export class Loot {
  items: Item[] = [];
  private oreGeo = new THREE.OctahedronGeometry(0.9, 0);
  private powGeo = new THREE.IcosahedronGeometry(1.6, 0);
  private mats = new Map<number, THREE.MeshBasicMaterial>();
  constructor(private scene: THREE.Scene) {
    for (let i = 0; i < 110; i++) {
      const mesh = new THREE.Mesh(this.oreGeo, this.mat(0xffffff)); mesh.visible = false; scene.add(mesh);
      this.items.push({ mesh, vel: new THREE.Vector3(), life: 0, alive: false, ore: 0, power: null });
    }
  }
  private mat(c: number) {
    let m = this.mats.get(c);
    if (!m) { m = new THREE.MeshBasicMaterial({ color: c, wireframe: false }); this.mats.set(c, m); }
    return m;
  }
  spawn(p: THREE.Vector3, ore: OreId, power: PowerId | null = null) {
    const it = this.items.find(x => !x.alive); if (!it) return;
    it.alive = true; it.ore = ore; it.power = power; it.life = power ? 30 : 40;
    it.mesh.geometry = power ? this.powGeo : this.oreGeo;
    it.mesh.material = this.mat(power ? POWERS[power].color : ORES[ore].color);
    it.mesh.position.copy(p); it.mesh.visible = true;
    it.vel.set(Math.random() - 0.5, (Math.random() - 0.5) * 0.4, Math.random() - 0.5).multiplyScalar(power ? 8 : 18);
  }
  /** Mueve objetos, aplica imán y devuelve los recogidos. */
  update(dt: number, t: number, ship: THREE.Vector3, magnet: number, canOre: boolean) {
    const got: Item[] = [];
    for (const it of this.items) {
      if (!it.alive) continue;
      it.life -= dt;
      if (it.life <= 0) { it.alive = false; it.mesh.visible = false; continue; }
      const d = it.mesh.position.distanceTo(ship);
      if (d < magnet && (canOre || it.power)) {
        const pull = (1 - d / magnet) * 160 + 20;
        it.vel.lerp(ship.clone().sub(it.mesh.position).normalize().multiplyScalar(pull), Math.min(1, dt * 4));
      } else it.vel.multiplyScalar(Math.exp(-0.8 * dt));
      it.mesh.position.addScaledVector(it.vel, dt);
      it.mesh.rotation.set(t * 2, t * 3, 0);
      it.mesh.scale.setScalar((it.life < 5 ? (Math.sin(t * 20) > 0 ? 1 : 0.4) : 1) * (1 + Math.sin(t * 6) * 0.15));
      if (d < 5 && (canOre || it.power)) { it.alive = false; it.mesh.visible = false; got.push(it); }
    }
    return got;
  }
  clear() { this.items.forEach(i => { i.alive = false; i.mesh.visible = false; }); }
  dispose() {
    this.items.forEach(i => this.scene.remove(i.mesh));
    this.oreGeo.dispose(); this.powGeo.dispose(); this.mats.forEach(m => m.dispose());
  }
}

/** Sonido procedural con Web Audio API: efectos, zumbido del motor y música ambiental. */
export class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private engine: GainNode | null = null;
  private engOsc: OscillatorNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private muted = false;
  private musicT = 0; private step = 0;
  musicOn = false;
  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (!AC) return;
    const ctx: AudioContext = new AC(); this.ctx = ctx;
    this.master = ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.5; this.master.connect(ctx.destination);
    const len = ctx.sampleRate; this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0); for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.engine = ctx.createGain(); this.engine.gain.value = 0;
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 380;
    this.engOsc = ctx.createOscillator(); this.engOsc.type = 'sawtooth'; this.engOsc.frequency.value = 52;
    this.engOsc.connect(f); f.connect(this.engine); this.engine.connect(this.master); this.engOsc.start();
  }
  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05); }
  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0) {
    if (!this.ctx || !this.master) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.02);
  }
  private noise(dur: number, vol: number, freq: number) {
    if (!this.ctx || !this.master || !this.noiseBuf) return;
    const t = this.ctx.currentTime;
    const s = this.ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(freq, t); f.frequency.exponentialRampToValueAtTime(60, t + dur);
    const g = this.ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t); s.stop(t + dur);
  }
  laser() { this.tone(1400, 0.09, 'square', 0.05, 0.35); }
  enemyLaser() { this.tone(520, 0.14, 'sawtooth', 0.04, 0.5); }
  hitRock() { this.noise(0.08, 0.12, 2200); }
  hurt() { this.noise(0.25, 0.3, 900); this.tone(120, 0.25, 'square', 0.08, 0.5); }
  boom(big = false) { this.noise(big ? 1.2 : 0.6, big ? 0.6 : 0.4, big ? 1400 : 2400); this.tone(big ? 70 : 110, big ? 0.9 : 0.4, 'sine', 0.3, 0.3); }
  pickup(k = 0) { this.tone(880 + k * 220, 0.08, 'triangle', 0.08, 1.5); }
  power() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.18, 'triangle', 0.1, 1, i * 0.06)); }
  dock() { [392, 523, 659].forEach((f, i) => this.tone(f, 0.4, 'sine', 0.12, 1, i * 0.12)); }
  coin() { this.tone(1318, 0.12, 'square', 0.05, 1, 0); this.tone(1760, 0.2, 'square', 0.05, 1, 0.07); }
  alarm() { this.tone(660, 0.15, 'square', 0.06, 1); this.tone(440, 0.15, 'square', 0.06, 1, 0.16); }
  deny() { this.tone(160, 0.2, 'square', 0.08, 0.8); }
  setThrust(v: number) {
    if (!this.ctx || !this.engine || !this.engOsc) return;
    const t = this.ctx.currentTime;
    this.engine.gain.setTargetAtTime(0.02 + v * 0.07, t, 0.1);
    this.engOsc.frequency.setTargetAtTime(48 + v * 40, t, 0.15);
  }
  /** Música ambiental: arpegio lento sobre acordes menores. */
  tick(dt: number) {
    if (!this.ctx || !this.musicOn) return;
    this.musicT -= dt; if (this.musicT > 0) return;
    this.musicT = 0.32;
    const chords = [[220, 261.6, 329.6], [174.6, 220, 261.6], [196, 246.9, 293.7], [164.8, 196, 246.9]];
    const c = chords[Math.floor(this.step / 16) % 4];
    const n = c[[0, 1, 2, 1, 2, 0, 2, 1][this.step % 8]] * (this.step % 16 >= 8 ? 2 : 1);
    this.tone(n, 0.6, 'sine', 0.035);
    if (this.step % 16 === 0) c.forEach(f => this.tone(f / 2, 5, 'triangle', 0.025));
    this.step++;
  }
  stopEngine() { this.setThrust(0); if (this.engine && this.ctx) this.engine.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1); }
  dispose() { try { this.engOsc?.stop(); this.ctx?.close(); } catch { /* ya cerrado */ } this.ctx = null; }
}

