const RECORD_KEY = 'galaxia-records';
export function loadRecords(): Record<DiffId, number> {
  try { const r = JSON.parse(localStorage.getItem(RECORD_KEY) || '{}'); return { facil: r.facil || 0, normal: r.normal || 0, dificil: r.dificil || 0 }; }
  catch { return { facil: 0, normal: 0, dificil: 0 }; }
}
export function saveRecord(diff: DiffId, score: number): boolean {
  const r = loadRecords();
  if (score <= r[diff]) return false;
  r[diff] = score;
  try { localStorage.setItem(RECORD_KEY, JSON.stringify(r)); } catch { /* sin almacenamiento */ }
  return true;
}

import * as THREE from 'three';
import { particleMaterial, glowTexture } from './shaders';

const MAX = 1400;

/** Sistema de partículas aditivas en un único Points (pool circular). */
export class Effects {
  private pos = new Float32Array(MAX * 3); private col = new Float32Array(MAX * 3); private size = new Float32Array(MAX);
  private vel = new Float32Array(MAX * 3); private base = new Float32Array(MAX * 3);
  private life = new Float32Array(MAX); private maxLife = new Float32Array(MAX); private s0 = new Float32Array(MAX);
  private next = 0;
  private geo = new THREE.BufferGeometry(); private mat = particleMaterial(); private points: THREE.Points;
  private flashes: { s: THREE.Sprite; t: number; dur: number; size: number }[] = [];
  private flashTex = glowTexture('rgba(255,255,255,1)', 'rgba(255,170,90,0.45)');
  private tmpC = new THREE.Color();
  constructor(private scene: THREE.Scene) {
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    this.geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    this.points = new THREE.Points(this.geo, this.mat); this.points.frustumCulled = false;
    scene.add(this.points);
    for (let i = 0; i < 10; i++) {
      const m = new THREE.SpriteMaterial({ map: this.flashTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true });
      const s = new THREE.Sprite(m); s.visible = false; scene.add(s);
      this.flashes.push({ s, t: 0, dur: 1, size: 1 });
    }
  }
  setScale(h: number) { this.mat.uniforms.uScale.value = h * 0.9; }
  spawn(p: THREE.Vector3, vx: number, vy: number, vz: number, color: number, size: number, life: number) {
    const i = this.next; this.next = (this.next + 1) % MAX;
    this.pos[i * 3] = p.x; this.pos[i * 3 + 1] = p.y; this.pos[i * 3 + 2] = p.z;
    this.vel[i * 3] = vx; this.vel[i * 3 + 1] = vy; this.vel[i * 3 + 2] = vz;
    this.tmpC.setHex(color); this.base[i * 3] = this.tmpC.r; this.base[i * 3 + 1] = this.tmpC.g; this.base[i * 3 + 2] = this.tmpC.b;
