    _w.copy(ship.pos).addScaledVector(f, -24 - sp * 0.06).add(_v.set(0, 8.5, 0));
    cam.position.lerp(_w, Math.min(1, dt * 4));
    _look.copy(ship.pos).addScaledVector(f, 26);
    if (this.shake > 0) {
      const k = this.shake * 1.6;
      cam.position.add(_v.set((Math.random() - 0.5) * k, (Math.random() - 0.5) * k, (Math.random() - 0.5) * k));
      this.shake = Math.max(0, this.shake - dt * 1.8);
    }
    cam.lookAt(_look);
    const fov = 62 + Math.min(1, sp / this.stats.maxSpeed) * 8 + (ship.boosting ? 6 : 0);
    if (Math.abs(cam.fov - fov) > 0.05) { cam.fov += (fov - cam.fov) * Math.min(1, dt * 3); cam.updateProjectionMatrix(); }
  }
  dispose() {
    cancelAnimationFrame(this.raf); this.ro.disconnect(); this.input.detach(); this.sfx.dispose();
    this.sys.dispose(); this.field.dispose(); this.loot.dispose(); this.pirates.dispose(); this.ship.dispose(); this.bolts.dispose(); this.fx.dispose();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

/** Entrada unificada: teclado en window + controles táctiles. */
export interface InputState { thrust: number; turn: number; fire: boolean; boost: boolean }

export class Input {
  state: InputState = { thrust: 0, turn: 0, fire: false, boost: false };
  touch = { x: 0, y: 0, fire: false, boost: false, active: false };
  onPause: (() => void) | null = null;
  onDock: (() => void) | null = null;
  onAnyKey: (() => void) | null = null;
  private keys = new Set<string>();
  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    this.onAnyKey?.();
    if ((k === 'Escape' || k === 'KeyP') && !e.repeat) { this.onPause?.(); return; }
    if ((k === 'KeyE' || k === 'Enter') && !e.repeat) this.onDock?.();
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private blur = () => { this.keys.clear(); };
  attach() { window.addEventListener('keydown', this.down); window.addEventListener('keyup', this.up); window.addEventListener('blur', this.blur); }
  detach() { window.removeEventListener('keydown', this.down); window.removeEventListener('keyup', this.up); window.removeEventListener('blur', this.blur); }
  update() {
    const k = this.keys; const s = this.state;
    let th = 0, tu = 0;
    if (k.has('ArrowUp') || k.has('KeyW')) th += 1;
    if (k.has('ArrowDown') || k.has('KeyS')) th -= 1;
    if (k.has('ArrowLeft') || k.has('KeyA')) tu -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) tu += 1;
    if (this.touch.active) { th += -this.touch.y; tu += this.touch.x; }
    s.thrust = Math.max(-1, Math.min(1, th));
    s.turn = Math.max(-1, Math.min(1, tu));
    s.fire = k.has('Space') || k.has('KeyJ') || this.touch.fire;
    s.boost = k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.boost;
  }
  reset() {
    this.keys.clear();
    this.state = { thrust: 0, turn: 0, fire: false, boost: false };
    Object.assign(this.touch, { x: 0, y: 0, fire: false, boost: false, active: false });
  }
}

/** Generador pseudoaleatorio con semilla (mulberry32). */
export type Rng = () => number;
export function makeRng(seed: number): Rng {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export const rr = (rng: Rng, a: number, b: number) => a + (b - a) * rng();
export const pick = <T,>(rng: Rng, arr: T[]): T => arr[Math.floor(rng() * arr.length)];

function hash(x: number, y: number, z: number) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(z, 1274126177);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
const sm = (t: number) => t * t * (3 - 2 * t);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/** Ruido de valor 3D en [0,1]. */
export function noise3(x: number, y: number, z: number) {
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const fx = sm(x - xi), fy = sm(y - yi), fz = sm(z - zi);
  const c = (dx: number, dy: number, dz: number) => hash(xi + dx, yi + dy, zi + dz);
  return lerp(
    lerp(lerp(c(0, 0, 0), c(1, 0, 0), fx), lerp(c(0, 1, 0), c(1, 1, 0), fx), fy),
    lerp(lerp(c(0, 0, 1), c(1, 0, 1), fx), lerp(c(0, 1, 1), c(1, 1, 1), fx), fy), fz);
}
export function fbm3(x: number, y: number, z: number, oct = 4) {
  let a = 0.5, s = 0, f = 1;
  for (let i = 0; i < oct; i++) { s += a * noise3(x * f, y * f, z * f); f *= 2.03; a *= 0.5; }
  return s;
}

const SYL = ['ka', 'tor', 've', 'lun', 'xa', 'ri', 'on', 'pha', 'nem', 'sol', 'dra', 'ix', 'cer', 'mo', 'ae', 'zu'];
export function planetName(rng: Rng) {
  const n = 2 + Math.floor(rng() * 2);
  let s = ''; for (let i = 0; i < n; i++) s += pick(rng, SYL);
  return s.charAt(0).toUpperCase() + s.slice(1);
}

import * as THREE from 'three';
import { glowTexture } from './shaders';
import type { Bolts } from './weapons';
import type { Effects } from './effects';
import type { Difficulty } from './economy';

export type PirateType = 'caza' | 'corsario' | 'elite';
export const PIRATE_SPECS: Record<PirateType, { name: string; hp: number; speed: number; turn: number; fire: number; dmg: number; bounty: number; r: number; color: number }> = {
  caza: { name: 'Caza pirata', hp: 30, speed: 64, turn: 2.4, fire: 1.1, dmg: 6, bounty: 60, r: 4.5, color: 0xd8203a },
  corsario: { name: 'Corsario', hp: 110, speed: 34, turn: 1.2, fire: 1.7, dmg: 8, bounty: 160, r: 8, color: 0x8a2ad8 },
  elite: { name: 'Élite carmesí', hp: 220, speed: 56, turn: 2.0, fire: 0.38, dmg: 6, bounty: 340, r: 6.5, color: 0xffa01a },
};

export interface Pirate { type: PirateType; group: THREE.Group; pos: THREE.Vector3; yaw: number; speed: number; hp: number; maxHp: number; fireCd: number; burst: number; orbit: number; hitT: number; bob: number }
const _up = new THREE.Vector3(0, 1, 0); const _d = new THREE.Vector3(); const _aim = new THREE.Vector3(); const _o = new THREE.Vector3();

/** Flotas piratas: modelos, IA de persecución con esquiva y disparo con anticipación. */
export class Pirates {
  list: Pirate[] = [];
  private templates: Partial<Record<PirateType, THREE.Group>> = {};
  private geos: THREE.BufferGeometry[] = [];
  private mats: THREE.Material[] = [];
  private glowTex = glowTexture('rgba(255,220,200,1)', 'rgba(255,60,60,0.45)');
  private glowMat = new THREE.SpriteMaterial({ map: this.glowTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true });
  constructor(private scene: THREE.Scene) {}
  private geo<T extends THREE.BufferGeometry>(g: T) { this.geos.push(g); return g; }
  private mat(color: number, emissive = 0) {
    const m = new THREE.MeshStandardMaterial({ color, emissive, metalness: 0.6, roughness: 0.35 }); this.mats.push(m); return m;
  }
  private build(type: PirateType) {
    const g = new THREE.Group(); const sp = PIRATE_SPECS[type];
    const hull = this.mat(0x6a6478); const acc = this.mat(sp.color, sp.color & 0x7f7f7f);
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, p: [number, number, number], r: [number, number, number] = [0, 0, 0], s: [number, number, number] = [1, 1, 1]) => {
      const mesh = new THREE.Mesh(geo, m); mesh.position.set(...p); mesh.rotation.set(...r); mesh.scale.set(...s); g.add(mesh);
    };
    if (type === 'caza') {
      add(this.geo(new THREE.OctahedronGeometry(2.2, 0)), hull, [0, 0, 0], [0, 0, 0], [1, 0.6, 2]);
      for (const s of [-1, 1]) add(this.geo(new THREE.BoxGeometry(5, 0.3, 2.2)), acc, [s * 3, 0, 1], [0, s * -0.5, s * 0.3]);
    } else if (type === 'corsario') {
      add(this.geo(new THREE.BoxGeometry(6, 3, 11)), hull, [0, 0, 0]);
      add(this.geo(new THREE.CylinderGeometry(1.2, 2.5, 5, 6)), acc, [0, 0, -7], [-Math.PI / 2, 0, 0]);
      for (const s of [-1, 1]) {
        add(this.geo(new THREE.BoxGeometry(3, 5, 7)), acc, [s * 4.5, 0, 1]);
        add(this.geo(new THREE.CylinderGeometry(0.5, 0.5, 6, 6)), hull, [s * 4.5, 2.5, -4], [Math.PI / 2, 0, 0]);
      }
    } else {
      add(this.geo(new THREE.ConeGeometry(2, 9, 5)), hull, [0, 0, -1], [-Math.PI / 2, 0, 0]);
      for (const s of [-1, 1]) {
        add(this.geo(new THREE.BoxGeometry(7, 0.4, 3)), acc, [s * 4, 0, 2], [0, s * 0.6, 0]);
        add(this.geo(new THREE.BoxGeometry(0.4, 3, 3)), acc, [s * 7, 0.5, 3.5]);
      }
    }
    const glow = new THREE.Sprite(this.glowMat); glow.scale.setScalar(sp.r * 1.6); glow.position.set(0, 0, sp.r); g.add(glow);
    g.scale.setScalar(1.35); return g;
  }
  spawn(type: PirateType, pos: THREE.Vector3, yaw: number, diff: Difficulty) {
    const sp = PIRATE_SPECS[type];
    let tpl = this.templates[type];
    if (!tpl) { tpl = this.build(type); this.templates[type] = tpl; }
    const group = tpl.clone(); group.position.copy(pos); this.scene.add(group);
    const hp = sp.hp * diff.hp;
    this.list.push({ type, group, pos: pos.clone(), yaw, speed: sp.speed, hp, maxHp: hp, fireCd: 0.4 + Math.random() * 0.8, burst: 0, orbit: Math.random() < 0.5 ? 1 : -1, hitT: 0, bob: Math.random() * 6 });
  }
  /** Oleada que entra desde un punto alejado alrededor del jugador. */
  wave(center: THREE.Vector3, ahead: THREE.Vector3, threat: number, diff: Difficulty, first = false) {
    const n = Math.min(9, Math.round((2 + threat * 0.9) * diff.spawn));
    const base = first ? Math.atan2(ahead.x, ahead.z) : Math.random() * Math.PI * 2;
    const dist = first ? 105 : 330;
    for (let i = 0; i < n; i++) {
      const a = base + (i - (n - 1) / 2) * (first ? 0.3 : 0.16);
      const p = new THREE.Vector3(center.x + Math.sin(a) * (dist + i * 12), (Math.random() - 0.5) * 20, center.z + Math.cos(a) * (dist + i * 12));
      const r = Math.random();
      const type: PirateType = threat >= 3 && r < 0.12 + threat * 0.02 ? 'elite' : threat >= 2 && r < 0.45 ? 'corsario' : 'caza';
      this.spawn(type, p, Math.atan2(-(center.x - p.x), -(center.z - p.z)), diff);
    }
    return n;
  }
  update(dt: number, t: number, target: THREE.Vector3, tvel: THREE.Vector3, bolts: Bolts, diff: Difficulty, onFire: () => void) {
    for (const p of this.list) {
      const sp = PIRATE_SPECS[p.type];
      _d.subVectors(target, p.pos); const dist = _d.length();
      // Persecución con órbita lateral cuando está cerca
      _o.set(-_d.z, 0, _d.x).normalize().multiplyScalar(p.orbit * (dist < 90 ? 70 : 20));
      const goal = _aim.copy(target).add(_o);
      if (dist < 35) goal.copy(p.pos).sub(_d.clone().multiplyScalar(3)).add(_o);
      const want = Math.atan2(-(goal.x - p.pos.x), -(goal.z - p.pos.z));
      let dy = want - p.yaw; dy = Math.atan2(Math.sin(dy), Math.cos(dy));
      p.yaw += Math.max(-sp.turn * dt, Math.min(sp.turn * dt, dy));
      p.speed += (sp.speed * (dist > 200 ? 1.35 : 1) - p.speed) * Math.min(1, dt);
      p.pos.x += -Math.sin(p.yaw) * p.speed * dt; p.pos.z += -Math.cos(p.yaw) * p.speed * dt;
      p.pos.y += (target.y + Math.sin(t + p.bob) * 6 - p.pos.y) * Math.min(1, dt * 0.8);
      p.group.position.copy(p.pos);
      p.group.rotation.set(0, p.yaw, -dy * 0.8);
      if (p.hitT > 0) { p.hitT -= dt; p.group.scale.setScalar(1.35 + p.hitT); } else p.group.scale.setScalar(1.35);
      // Disparo
      p.fireCd -= dt;
      const fx = -Math.sin(p.yaw), fz = -Math.cos(p.yaw);
      const facing = (_d.x * fx + _d.z * fz) / Math.max(dist, 0.001);
      if (p.fireCd <= 0 && dist < 280 && facing > 0.9) {
        const lead = dist / 170;
        _aim.copy(target).addScaledVector(tvel, lead * 0.8).sub(p.pos).normalize();
        const muzzle = p.pos.clone().addScaledVector(_aim, sp.r + 1);
        const dmg = sp.dmg * diff.dmg;
        if (p.type === 'corsario') {
          for (const s of [-0.12, 0, 0.12]) bolts.fire(muzzle, _aim.clone().applyAxisAngle(_up, s), 150, true, dmg);
          p.fireCd = sp.fire;
        } else {
          bolts.fire(muzzle, _aim, 170, true, dmg);
          if (p.type === 'elite') { p.burst++; p.fireCd = p.burst % 4 === 0 ? 1.6 : sp.fire; } else p.fireCd = sp.fire * (0.8 + Math.random() * 0.4);
        }
        onFire();
      }
    }
  }
  /** Comprueba impactos de los láseres del jugador. */
  hits(bolts: Bolts, fx: Effects, onHit: (p: Pirate, killed: boolean) => void) {
    for (const b of bolts.list) {
      if (!b.alive || b.enemy) continue;
      for (const p of this.list) {
        const r = PIRATE_SPECS[p.type].r + 1.5;
        if (p.pos.distanceToSquared(b.mesh.position) > r * r) continue;
        bolts.kill(b); p.hp -= b.dmg; p.hitT = 0.15;
        fx.burst(b.mesh.position, 0x9ffcff, 8, 25, 1.6, 0.4);
        onHit(p, p.hp <= 0);
        break;
      }
    }
    this.list = this.list.filter(p => { if (p.hp > 0) return true; this.scene.remove(p.group); return false; });
  }
  clear() { this.list.forEach(p => this.scene.remove(p.group)); this.list = []; }
  dispose() { this.clear(); this.geos.forEach(g => g.dispose()); this.mats.forEach(m => m.dispose()); this.glowMat.dispose(); this.glowTex.dispose(); }
}

import type { PlayerShip } from './ship';
import type { SpaceSystem } from './space';
import type { AsteroidField } from './asteroids';
import type { Pirates } from './pirates';
import { PIRATE_SPECS } from './pirates';

/** Radar circular orientado con la proa de la nave (vista cenital). */
export function drawRadar(c: HTMLCanvasElement, ship: PlayerShip, sys: SpaceSystem, field: AsteroidField, pirates: Pirates, t: number) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const W = c.clientWidth, H = c.clientHeight; if (!W || !H) return;
  if (c.width !== Math.round(W * dpr)) { c.width = Math.round(W * dpr); c.height = Math.round(H * dpr); }
  const g = c.getContext('2d'); if (!g) return;
  g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, W, H);
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 3, RANGE = 650, k = R / RANGE;
  const cos = Math.cos(ship.yaw), sin = Math.sin(ship.yaw);
  // Mundo -> radar: la proa apunta hacia arriba
  const map = (x: number, z: number): [number, number] => {
    const dx = x - ship.pos.x, dz = z - ship.pos.z;
    const rx = dx * cos - dz * sin, rz = dx * sin + dz * cos;
    return [cx + rx * k, cy + rz * k];
  };
  g.save(); g.beginPath(); g.arc(cx, cy, R, 0, Math.PI * 2); g.clip();
  const bg = g.createRadialGradient(cx, cy, 0, cx, cy, R);
  bg.addColorStop(0, 'rgba(20,40,80,0.55)'); bg.addColorStop(1, 'rgba(8,12,35,0.75)');
  g.fillStyle = bg; g.fillRect(0, 0, W, H);
  g.strokeStyle = 'rgba(120,220,255,0.18)'; g.lineWidth = 1;
  for (const f of [0.33, 0.66]) { g.beginPath(); g.arc(cx, cy, R * f, 0, Math.PI * 2); g.stroke(); }
  g.beginPath(); g.moveTo(cx, cy - R); g.lineTo(cx, cy + R); g.moveTo(cx - R, cy); g.lineTo(cx + R, cy); g.stroke();
  // Barrido
  const a = (t * 1.6) % (Math.PI * 2);
  const sw = g.createLinearGradient(cx, cy, cx + Math.cos(a) * R, cy + Math.sin(a) * R);
  sw.addColorStop(0, 'rgba(120,255,230,0.0)'); sw.addColorStop(1, 'rgba(120,255,230,0.25)');
  g.fillStyle = sw; g.beginPath(); g.moveTo(cx, cy); g.arc(cx, cy, R, a - 0.4, a); g.closePath(); g.fill();
  for (const p of sys.planets) {
    const [x, y] = map(p.pos.x, p.pos.z);
    g.fillStyle = p.color + '88'; g.beginPath(); g.arc(x, y, Math.max(3, p.radius * k), 0, Math.PI * 2); g.fill();
  }
  for (const cl of field.clusters) {
    const [x, y] = map(cl.center.x, cl.center.z);
    g.strokeStyle = 'rgba(200,170,140,0.5)'; g.setLineDash([3, 3]); g.beginPath(); g.arc(x, y, cl.radius * k, 0, Math.PI * 2); g.stroke(); g.setLineDash([]);
  }
  g.fillStyle = 'rgba(210,190,170,0.75)';
  for (const r of field.rocks) {
    if (!r.alive || r.pos.distanceToSquared(ship.pos) > RANGE * RANGE) continue;
    const [x, y] = map(r.pos.x, r.pos.z); g.fillRect(x - 0.8, y - 0.8, 1.6, 1.6);
  }
  const [sx, sy] = map(sys.stationPos.x, sys.stationPos.z);
  g.fillStyle = '#7ff6ff'; g.fillRect(sx - 4, sy - 4, 8, 8);
  for (const p of pirates.list) {
    const [x, y] = map(p.pos.x, p.pos.z);
    g.fillStyle = '#' + PIRATE_SPECS[p.type].color.toString(16).padStart(6, '0');
    g.beginPath(); g.arc(x, y, p.type === 'caza' ? 2.6 : 3.6, 0, Math.PI * 2); g.fill();
  }
  g.restore();
  // Borde y estación fuera de rango
  g.strokeStyle = 'rgba(120,220,255,0.6)'; g.lineWidth = 1.5; g.beginPath(); g.arc(cx, cy, R, 0, Math.PI * 2); g.stroke();
  const ddx = sx - cx, ddy = sy - cy, dd = Math.hypot(ddx, ddy);
  if (dd > R) { g.fillStyle = '#7ff6ff'; g.beginPath(); g.arc(cx + ddx / dd * (R - 5), cy + ddy / dd * (R - 5), 3.5, 0, Math.PI * 2); g.fill(); }
  g.fillStyle = '#ffffff'; g.beginPath(); g.moveTo(cx, cy - 6); g.lineTo(cx + 4, cy + 4); g.lineTo(cx - 4, cy + 4); g.closePath(); g.fill();
}

import * as THREE from 'three';
import { fbm3, noise3 } from './noise';

/** Ruido 3D en GLSL (solo para el horneado inicial de texturas en GPU). */
const GLSL_NOISE = `
float hash3(vec3 p){ p = fract(p*0.3183099 + 0.1); p *= 17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float noise3(vec3 x){
  vec3 i = floor(x); vec3 f = fract(x); f = f*f*(3.0-2.0*f);
  return mix(mix(mix(hash3(i), hash3(i+vec3(1.,0.,0.)), f.x), mix(hash3(i+vec3(0.,1.,0.)), hash3(i+vec3(1.,1.,0.)), f.x), f.y),
             mix(mix(hash3(i+vec3(0.,0.,1.)), hash3(i+vec3(1.,0.,1.)), f.x), mix(hash3(i+vec3(0.,1.,1.)), hash3(i+vec3(1.,1.,1.)), f.x), f.y), f.z);
}
float fbm(vec3 p){ float a = 0.5, s = 0.0; for (int i = 0; i < 5; i++) { s += a*noise3(p); p = p*2.03 + vec3(1.7, 9.2, 3.1); a *= 0.5; } return s; }
`;
const v3 = (c: THREE.ColorRepresentation) => { const k = new THREE.Color(c); return new THREE.Vector3(k.r, k.g, k.b); };

/** Renderiza un shader de pantalla completa a una textura (una sola vez). `d` = dirección esférica del texel. */
function bake(renderer: THREE.WebGLRenderer, w: number, h: number, body: string, uniforms: Record<string, { value: unknown }>) {
  const rt = new THREE.WebGLRenderTarget(w, h, { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, depthBuffer: false });
  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }`,
    fragmentShader: `${GLSL_NOISE}
      varying vec2 vUv; uniform float uSeed; uniform vec3 uA; uniform vec3 uB; uniform vec3 uC; uniform vec3 uSun; uniform float uType;
      void main(){
        float phi = vUv.x * 6.2831853; float th = (1.0 - vUv.y) * 3.1415927;
        vec3 d = vec3(-cos(phi)*sin(th), cos(th), sin(phi)*sin(th));
        ${body}
      }`,
    depthTest: false, depthWrite: false,
  });
  const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), mat);
  const sc = new THREE.Scene(); sc.add(quad);
  renderer.setRenderTarget(rt); renderer.render(sc, new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)); renderer.setRenderTarget(null);
  quad.geometry.dispose(); mat.dispose();
  return rt;
}

/** Nebulosa + vía láctea + resplandor solar en una textura de cielo. */
export function bakeNebula(renderer: THREE.WebGLRenderer, seed: number, colA: string, colB: string, sunDir: THREE.Vector3) {
  return bake(renderer, 2048, 1024, `
    vec3 q = d + vec3(uSeed);
    float n1 = fbm(q*2.0); float n2 = fbm(q*4.3 + vec3(5.2, 1.3, 0.0));
    float band = exp(-pow(d.y*2.4 + (n1-0.5)*1.8, 2.0)*1.6);
    vec3 col = vec3(0.012, 0.01, 0.035);
    col += uA * pow(n1, 2.6) * 2.2 * (0.35 + band);
    col += uB * pow(n2, 3.2) * 2.6 * band;
    col *= 1.0 - smoothstep(0.42, 0.72, fbm(q*7.0 + 3.0))*0.65*band;
    col += vec3(1.0, 0.9, 1.0) * pow(fbm(q*24.0), 7.0) * band * 1.4;
    float s = max(dot(d, uSun), 0.0);
    col += vec3(1.0, 0.75, 0.45) * (pow(s, 12.0)*0.35 + pow(s, 3.0)*0.08);
    gl_FragColor = vec4(col, 1.0);`,
    { uSeed: { value: seed % 97 }, uA: { value: v3(colA) }, uB: { value: v3(colB) }, uC: { value: v3(0) }, uSun: { value: sunDir.clone() }, uType: { value: 0 } });
}

export type PlanetType = 0 | 1 | 2 | 3 | 4; // rocoso, gaseoso, oceánico, volcánico, helado
/** Superficie del planeta (albedo en RGB, máscara de lava emisiva en A). */
export function bakePlanet(renderer: THREE.WebGLRenderer, type: PlanetType, a: string, b: string, c: string, seed: number) {
  return bake(renderer, 1024, 512, `
    vec3 q = d + vec3(uSeed); float n = fbm(q*2.6); vec3 col; float emit = 0.0;
    if (uType < 0.5) {
      float n2 = fbm(q*9.0);
      col = mix(uA, uB, smoothstep(0.3, 0.7, n)); col = mix(col, uC, smoothstep(0.5, 0.75, n2)*0.7); col *= 0.75 + 0.5*n2;
    } else if (uType < 1.5) {
      float b = d.y*5.0 + (n-0.5)*2.2 + fbm(vec3(d.y*18.0, uSeed, 0.0))*0.8;
      col = mix(uA, uB, sin(b*3.0)*0.5 + 0.5); col = mix(col, uC, smoothstep(0.55, 0.85, fbm(q*4.0)));
    } else if (uType < 2.5) {
      float land = smoothstep(0.5, 0.54, n);
      col = mix(uA * (0.7 + 0.6*fbm(q*6.0)), uB * (0.7 + 0.6*fbm(q*11.0)), land);
      col = mix(col, vec3(0.92, 0.95, 1.0), smoothstep(0.78, 0.9, abs(d.y) + n*0.1));
      col = mix(col, vec3(1.0), smoothstep(0.52, 0.78, fbm(q*4.5 + 7.0))*0.85);
    } else if (uType < 3.5) {
      col = mix(uA, uB, n) * 0.6; emit = smoothstep(0.08, 0.0, abs(fbm(q*6.0) - 0.5));
    } else {
      col = mix(uA, uB, smoothstep(0.35, 0.65, n)); col = mix(col, uC, smoothstep(0.62, 0.66, fbm(q*12.0))*0.8);
    }
    gl_FragColor = vec4(col, emit);`,
    { uSeed: { value: seed }, uA: { value: v3(a) }, uB: { value: v3(b) }, uC: { value: v3(c) }, uSun: { value: new THREE.Vector3() }, uType: { value: type } });
}

export function skyMaterial(tex: THREE.Texture) {
  return new THREE.ShaderMaterial({
    uniforms: { uTex: { value: tex } },
    vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `varying vec2 vUv; uniform sampler2D uTex; void main(){ gl_FragColor = vec4(texture2D(uTex, vUv).rgb, 1.0); }`,
    side: THREE.BackSide, depthWrite: false,
  });
}

/** Estrellas puntuales con parpadeo. */
export function starMaterial() {
  return new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 }, uScale: { value: 1 } },
    vertexShader: `attribute float aSize; attribute vec3 aColor; varying vec3 vCol; uniform float uTime; uniform float uScale;
      void main(){ vCol = aColor * (0.75 + 0.25*sin(uTime*2.0 + position.x*0.05 + position.y*0.07));
        gl_PointSize = aSize * uScale; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `varying vec3 vCol; void main(){ float a = smoothstep(0.5, 0.0, length(gl_PointCoord - 0.5)); gl_FragColor = vec4(vCol * a * a, 1.0); }`,
    blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
  });
}

/** Planeta iluminado por el sol con borde atmosférico y lava que brilla en la cara nocturna. */
export function planetMaterial(tex: THREE.Texture, atmo: string, lava: string, sunDir: THREE.Vector3) {
  return new THREE.ShaderMaterial({
    uniforms: { uTex: { value: tex }, uAtmo: { value: v3(atmo) }, uLava: { value: v3(lava) }, uSun: { value: sunDir } },
    vertexShader: `varying vec3 vN; varying vec3 vW; varying vec2 vUv;
      void main(){ vUv = uv; vN = normalize(mat3(modelMatrix) * normal); vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz;
        gl_Position = projectionMatrix * viewMatrix * w; }`,
    fragmentShader: `varying vec3 vN; varying vec3 vW; varying vec2 vUv; uniform sampler2D uTex; uniform vec3 uAtmo; uniform vec3 uLava; uniform vec3 uSun;
      void main(){ vec4 t = texture2D(uTex, vUv);
        vec3 N = normalize(vN); float d = dot(N, uSun);
        float rim = pow(1.0 - max(dot(N, normalize(cameraPosition - vW)), 0.0), 3.0);
        vec3 c = t.rgb * (0.035 + 1.1*max(d, 0.0)) + uAtmo * rim * smoothstep(-0.35, 0.5, d) * 0.9;
        c += uLava * t.a * 1.6 * (0.4 + 0.6*smoothstep(0.2, -0.3, d));
        gl_FragColor = vec4(c, 1.0); }`,
  });
}

/** Halo atmosférico (cáscara trasera aditiva). */
export function atmoMaterial(color: string, sunDir: THREE.Vector3, power = 1) {
  return new THREE.ShaderMaterial({
    uniforms: { uCol: { value: v3(color) }, uSun: { value: sunDir }, uPow: { value: power } },
    vertexShader: `varying vec3 vN; varying vec3 vR;
      void main(){ vN = normalize(normalMatrix * normal); vR = normalize(mat3(modelMatrix) * position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `varying vec3 vN; varying vec3 vR; uniform vec3 uCol; uniform vec3 uSun; uniform float uPow;
      void main(){ float i = pow(max(0.72 - dot(vN, vec3(0.0, 0.0, 1.0)), 0.0), 3.5);
        gl_FragColor = vec4(uCol * i * smoothstep(-0.45, 0.55, dot(vR, uSun)) * uPow, 1.0); }`,
    side: THREE.BackSide, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false,
  });
}

/** Anillos: perfil de bandas precalculado en CPU + sombra del planeta. */
export function ringMaterial(inner: number, outer: number, color: string, sunDir: THREE.Vector3, seed: number) {
  const W = 512, data = new Uint8Array(W * 4);
  for (let i = 0; i < W; i++) {
    const t = i / (W - 1), b = fbm3(t * 28, seed, 0, 5), b2 = noise3(t * 120, seed, 1);
    let a = Math.min(1, t / 0.04) * Math.min(1, (1 - t) / 0.08) * (0.25 + 0.75 * b) * (0.7 + 0.3 * b2);
    if (Math.abs(t - 0.62) < 0.015) a *= 0.15;
    data.set([Math.round(Math.min(1, 0.6 + 0.6 * b) * 255), 0, 0, Math.round(Math.max(0, a) * 255)], i * 4);
  }
  const band = new THREE.DataTexture(data, W, 1, THREE.RGBAFormat); band.magFilter = THREE.LinearFilter; band.minFilter = THREE.LinearFilter; band.needsUpdate = true;
  return new THREE.ShaderMaterial({
    uniforms: { uBand: { value: band }, uIn: { value: inner }, uOut: { value: outer }, uCol: { value: v3(color) }, uSun: { value: sunDir }, uR: { value: inner / 1.5 } },
    vertexShader: `varying float vR; varying vec3 vW; varying vec3 vC;
      void main(){ vR = length(position.xy); vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; vC = modelMatrix[3].xyz;
        gl_Position = projectionMatrix * viewMatrix * w; }`,
    fragmentShader: `varying float vR; varying vec3 vW; varying vec3 vC; uniform sampler2D uBand; uniform float uIn; uniform float uOut; uniform vec3 uCol; uniform vec3 uSun; uniform float uR;
      void main(){ vec4 b = texture2D(uBand, vec2((vR - uIn) / (uOut - uIn), 0.5));
        vec3 toC = vC - vW; float tca = dot(toC, uSun); float d2 = dot(toC, toC) - tca*tca;
        float sh = (tca > 0.0 && d2 < uR*uR) ? 0.12 : 1.0;
        gl_FragColor = vec4(uCol * b.r * sh, b.a * 0.9); }`,
    side: THREE.DoubleSide, transparent: true, depthWrite: false,
  });
}

/** Partículas aditivas con color y tamaño por vértice. */
export function particleMaterial() {
  return new THREE.ShaderMaterial({
    uniforms: { uScale: { value: 400 } },
    vertexShader: `attribute float aSize; attribute vec3 aColor; varying vec3 vCol; uniform float uScale;
      void main(){ vCol = aColor; vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * uScale / max(-mv.z, 1.0); gl_Position = projectionMatrix * mv; }`,
    fragmentShader: `varying vec3 vCol; void main(){ float a = smoothstep(0.5, 0.0, length(gl_PointCoord - 0.5)); gl_FragColor = vec4(vCol * a * a, 1.0); }`,
    blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
  });
}

/** Textura de resplandor radial para sprites. */
export function glowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(255,200,140,0.35)', size = 128) {
  const c = document.createElement('canvas'); c.width = c.height = size;
  const g = c.getContext('2d')!; const h = size / 2;
  const grd = g.createRadialGradient(h, h, 0, h, h, h);
  grd.addColorStop(0, inner); grd.addColorStop(0.18, mid); grd.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grd; g.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}

import * as THREE from 'three';
import type { InputState } from './input';
import type { ShipStats } from './economy';
import { glowTexture } from './shaders';
const _f = new THREE.Vector3();

/** Nave del jugador: modelo procedural + vuelo con inercia en el plano de la eclíptica. */
export class PlayerShip {
  group = new THREE.Group();
  pos = new THREE.Vector3();
  vel = new THREE.Vector3();
  yaw = 0; bank = 0; pitchVis = 0;
  hull = 100; shield = 60; fuel = 100;
  shieldDelay = 0; thrustVis = 0; boosting = false;
  private flames: THREE.Mesh[] = [];
  private glows: THREE.Sprite[] = [];
  private shieldMesh: THREE.Mesh;
  private disp: { dispose(): void }[] = [];
  constructor(private scene: THREE.Scene) {
    const g = this.group; const D = this.disp;
    const white = new THREE.MeshStandardMaterial({ color: 0xe8ecf5, metalness: 0.55, roughness: 0.3 });
    const accent = new THREE.MeshStandardMaterial({ color: 0xff7a2a, metalness: 0.4, roughness: 0.35, emissive: 0x401000 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x23263a, metalness: 0.7, roughness: 0.4 });
    const glass = new THREE.MeshStandardMaterial({ color: 0x1a8aff, emissive: 0x0a4aa0, metalness: 0.9, roughness: 0.1 });
    const flame = new THREE.MeshBasicMaterial({ color: 0x5ad8ff, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
    D.push(white, accent, dark, glass, flame);
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, p: [number, number, number], r: [number, number, number] = [0, 0, 0], s?: [number, number, number]) => {
      const mesh = new THREE.Mesh(geo, m); mesh.position.set(...p); mesh.rotation.set(...r); if (s) mesh.scale.set(...s); g.add(mesh); D.push(geo); return mesh;
    };
    add(new THREE.ConeGeometry(1.5, 8, 8), white, [0, 0, -1.5], [-Math.PI / 2, 0, 0]);
    add(new THREE.CylinderGeometry(1.5, 1.8, 3.5, 8), white, [0, 0, 4.2], [Math.PI / 2, 0, 0]);
    add(new THREE.SphereGeometry(1, 16, 10), glass, [0, 0.9, -0.5], [0, 0, 0], [0.9, 0.6, 1.9]);
    for (const s of [-1, 1]) {
      add(new THREE.BoxGeometry(6, 0.25, 3.2), white, [s * 3.6, -0.2, 3], [0, s * 0.35, 0]);
      add(new THREE.BoxGeometry(2.4, 0.3, 1), accent, [s * 5.8, -0.15, 3.9], [0, s * 0.35, 0]);
      add(new THREE.BoxGeometry(0.25, 1.8, 2), accent, [s * 6.4, 0.6, 4.4]);
      add(new THREE.CylinderGeometry(0.75, 0.95, 4, 10), dark, [s * 2.1, -0.1, 4.6], [Math.PI / 2, 0, 0]);
      const fl = add(new THREE.ConeGeometry(0.7, 5, 10), flame, [s * 2.1, -0.1, 9], [Math.PI / 2, 0, 0]);
      this.flames.push(fl);
    }
    const gt = glowTexture('rgba(200,250,255,1)', 'rgba(60,180,255,0.4)'); D.push(gt);
    for (const s of [-1, 1]) {
      const sm = new THREE.SpriteMaterial({ map: gt, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }); D.push(sm);
      const sp = new THREE.Sprite(sm); sp.position.set(s * 2.1, -0.1, 6.8); g.add(sp); this.glows.push(sp);
    }
    const shg = new THREE.SphereGeometry(8.5, 24, 16);
    const shm = new THREE.MeshBasicMaterial({ color: 0x4fd8ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, wireframe: true });
    this.shieldMesh = new THREE.Mesh(shg, shm); g.add(this.shieldMesh); D.push(shg, shm);
    scene.add(g);
  }
  forward(out = _f) { return out.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw)); }
  reset(s: ShipStats) {
    this.pos.set(0, 0, 30); this.vel.set(0, 0, -20); this.yaw = 0; this.bank = 0;
    this.hull = s.maxHull; this.shield = s.maxShield; this.fuel = s.fuel; this.shieldDelay = 0;
    this.group.visible = true;
  }
  update(dt: number, inp: InputState, s: ShipStats) {
    this.yaw -= inp.turn * s.turn * dt;
    const f = this.forward();
    const hasFuel = this.fuel > 0;
    this.boosting = inp.boost && inp.thrust > 0 && hasFuel;
    let th = 0;
    if (inp.thrust > 0 && hasFuel) {
      th = inp.thrust * (this.boosting ? 1.9 : 1);
      this.vel.addScaledVector(f, s.accel * th * dt);
      this.fuel = Math.max(0, this.fuel - dt * inp.thrust * (this.boosting ? 5 : 1.2));
    } else if (inp.thrust < 0) {
      this.vel.multiplyScalar(Math.exp(-2.2 * dt * -inp.thrust));
    }
    if (!hasFuel) this.fuel = Math.min(8, this.fuel + dt * 0.6); // reserva de emergencia
    this.vel.multiplyScalar(Math.exp(-0.22 * dt));
    // Reorienta suavemente la velocidad hacia la proa (control arcade)
    const sp = this.vel.length();
    if (sp > 1 && inp.thrust > 0) this.vel.lerp(_f.clone().multiplyScalar(sp), Math.min(1, dt * 0.9));
    const cap = s.maxSpeed * (this.boosting ? 1.55 : 1);
    if (sp > cap) this.vel.multiplyScalar(1 - Math.min(1, (sp - cap) / sp * dt * 3));
    this.vel.y += (-this.pos.y * 0.8 - this.vel.y * 1.2) * dt;
    this.pos.addScaledVector(this.vel, dt);
    this.bank += (-inp.turn * 0.65 - this.bank) * Math.min(1, dt * 5);
    this.thrustVis += (th - this.thrustVis) * Math.min(1, dt * 8);
    this.group.position.copy(this.pos);
    this.group.rotation.set(0, this.yaw, this.bank);
    const fl = 0.25 + this.thrustVis * (this.boosting ? 1.4 : 1) * (0.9 + Math.random() * 0.2);
    this.flames.forEach(m => { m.scale.set(1, fl, 1); m.position.z = 6.6 + fl * 2.5; });
    this.glows.forEach(g => g.scale.setScalar(3 + fl * 5));
    if (this.shieldDelay > 0) this.shieldDelay -= dt;
    else this.shield = Math.min(s.maxShield, this.shield + dt * 7);
    const sm = this.shieldMesh.material as THREE.MeshBasicMaterial;
    sm.opacity = Math.max(0, sm.opacity - dt * 1.5);
    this.shieldMesh.rotation.y += dt;
  }
  /** Aplica daño (escudo primero). Devuelve el daño al casco. */
  damage(d: number) {
    this.shieldDelay = 3;
    const sm = this.shieldMesh.material as THREE.MeshBasicMaterial;
    if (this.shield > 0) { sm.opacity = 0.55; const a = Math.min(this.shield, d); this.shield -= a; d -= a; }
    this.hull = Math.max(0, this.hull - d);
    return d;
  }
  dispose() { this.scene.remove(this.group); this.disp.forEach(d => d.dispose()); }
}

import * as THREE from 'three';
import { makeRng, rr, pick, planetName } from './noise';
import type { Rng } from './noise';
import { bakeNebula, bakePlanet, skyMaterial, starMaterial, planetMaterial, atmoMaterial, ringMaterial, glowTexture } from './shaders';
import type { PlanetType } from './shaders';
import { LIGHT_K } from './three-compat';

export interface Planet { name: string; pos: THREE.Vector3; radius: number; group: THREE.Group; body: THREE.Mesh; spin: number; mat: THREE.ShaderMaterial; color: string }
const PALETTES: { type: PlanetType; cols: [string, string, string, string] }[] = [
  { type: 1, cols: ['#d9a066', '#8a4b2a', '#f3e2c0', '#ffbb77'] },
  { type: 1, cols: ['#5b7fd6', '#a8c4ff', '#e8f0ff', '#7fb2ff'] },
  { type: 1, cols: ['#b06ad8', '#f0a3d0', '#ffe6f7', '#ff8fe0'] },
  { type: 2, cols: ['#0d3b78', '#4f8a3a', '#ffffff', '#6fb8ff'] },
  { type: 0, cols: ['#7a5a48', '#c9a27e', '#3d2c26', '#ffcf9a'] },
  { type: 3, cols: ['#2a1a18', '#4a2a22', '#ff5a1a', '#ff7744'] },
  { type: 4, cols: ['#bfe3ff', '#e9f6ff', '#7aa6d6', '#aee0ff'] },
];

export const SECTOR_R = 1400;

export class SpaceSystem {
  sunDir = new THREE.Vector3(-0.72, 0.36, 0.6).normalize();
  planets: Planet[] = [];
  station = new THREE.Group();
  stationPos = new THREE.Vector3(-75, 0, 50);
  sunLight: THREE.DirectionalLight;
  private sky: THREE.Mesh; private stars: THREE.Points; private sun = new THREE.Group();
  private rt: THREE.WebGLRenderTarget;
  private ring!: THREE.Group; private beacons: THREE.Mesh[] = [];
  private disposables: { dispose(): void }[] = [];
  constructor(private scene: THREE.Scene, renderer: THREE.WebGLRenderer, seed: number) {
    const rng = makeRng(seed);
    const nebs: [string, string][] = [['#5a2a9a', '#1fa3b8'], ['#a02a6a', '#3a4ac8'], ['#2a5ac8', '#d0558a'], ['#7a2ab0', '#e07a2a']];
    const [na, nb] = pick(rng, nebs);
    this.rt = bakeNebula(renderer, seed, na, nb, this.sunDir);
    const skyGeo = new THREE.SphereGeometry(4500, 48, 24);
    const skyMat = skyMaterial(this.rt.texture);
    this.sky = new THREE.Mesh(skyGeo, skyMat); this.sky.renderOrder = -10; this.sky.frustumCulled = false;
    scene.add(this.sky); this.disposables.push(skyGeo, skyMat);
    // Estrellas
    const N = 2600, pos = new Float32Array(N * 3), col = new Float32Array(N * 3), size = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      const u = rng() * 2 - 1, th = rng() * Math.PI * 2, r = Math.sqrt(1 - u * u);
      pos.set([Math.cos(th) * r * 3800, u * 3800, Math.sin(th) * r * 3800], i * 3);
      const t = rng(); const c = t < 0.15 ? [1, 0.75, 0.6] : t < 0.35 ? [0.7, 0.8, 1] : [1, 1, 1];
      const b = 0.5 + rng() * 0.7; col.set([c[0] * b, c[1] * b, c[2] * b], i * 3);
      size[i] = rng() < 0.04 ? rr(rng, 4, 6.5) : rr(rng, 1.2, 3);
    }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    sg.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
    sg.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
    const sm = starMaterial();
    this.stars = new THREE.Points(sg, sm); this.stars.frustumCulled = false; this.stars.renderOrder = -9;
    scene.add(this.stars); this.disposables.push(sg, sm);
    // Sol lejano
    const sprite = (tex: THREE.Texture, scale: number, color: number, op = 1) => {
      const m = new THREE.SpriteMaterial({ map: tex, color, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: op });
      const s = new THREE.Sprite(m); s.scale.setScalar(scale); this.sun.add(s); this.disposables.push(m); return s;
    };
    const gt = glowTexture('rgba(255,255,240,1)', 'rgba(255,190,110,0.5)'); this.disposables.push(gt);
    const gt2 = glowTexture('rgba(255,160,90,0.6)', 'rgba(255,90,60,0.12)'); this.disposables.push(gt2);
    sprite(gt, 520, 0xffffff); sprite(gt2, 1900, 0xffaa77, 0.9); sprite(gt2, 3600, 0x9966ff, 0.35);
    this.sun.renderOrder = -8; scene.add(this.sun);
    this.sunLight = new THREE.DirectionalLight(0xfff0dd, 1.6 * LIGHT_K);
    scene.add(this.sunLight, this.sunLight.target);
    scene.add(new THREE.HemisphereLight(0x8a7bd8, 0x1a1030, 0.55 * LIGHT_K));
    this.buildPlanets(rng, renderer);
    this.buildStation();
  }
  private buildPlanets(rng: Rng, renderer: THREE.WebGLRenderer) {
    const pals = PALETTES.slice().sort(() => rng() - 0.5);
    // El gigante anillado se coloca frente a la estación para la vista inicial.
    const spots = [
      new THREE.Vector3(-260, -70, -1000), new THREE.Vector3(780, 40, -420), new THREE.Vector3(-860, 20, 380),
      new THREE.Vector3(420, -30, 900), new THREE.Vector3(-300, 60, -1900),
    ];
    const giant = pals.find(p => p.type === 1)!;
    const order = [giant, ...pals.filter(p => p !== giant)];
    spots.forEach((sp, i) => {
      const pal = order[i % order.length];
      const R = i === 0 ? 170 : i === 4 ? 230 : pal.type === 1 ? rr(rng, 70, 110) : rr(rng, 34, 62);
      const jitter = i === 0 ? 0 : 120;
      const pos = sp.clone().add(new THREE.Vector3(rr(rng, -jitter, jitter), 0, rr(rng, -jitter, jitter)));
      const group = new THREE.Group(); group.position.copy(pos);
      const geo = new THREE.SphereGeometry(R, 64, 40);
      const tex = bakePlanet(renderer, pal.type, pal.cols[0], pal.cols[1], pal.cols[2], rr(rng, 0, 50));
      const mat = planetMaterial(tex.texture, pal.cols[3], pal.cols[2], this.sunDir);
      const body = new THREE.Mesh(geo, mat); body.rotation.z = rr(rng, -0.4, 0.4); group.add(body);
      const ag = new THREE.SphereGeometry(R * 1.13, 48, 32);
      const am = atmoMaterial(pal.cols[3], this.sunDir, pal.type === 3 ? 0.7 : 1.1);
      group.add(new THREE.Mesh(ag, am)); this.disposables.push(geo, mat, ag, am, tex);
      if (i === 0 || (pal.type === 1 && rng() < 0.6) || (i === 4 && rng() < 0.5)) {
        const rg = new THREE.RingGeometry(R * 1.5, R * 2.5, 160, 1);
        const rm = ringMaterial(R * 1.5, R * 2.5, i === 0 ? '#e8d2b0' : pal.cols[2], this.sunDir, rr(rng, 0, 30));
        const ring = new THREE.Mesh(rg, rm); ring.rotation.x = -Math.PI / 2 + 0.38; ring.rotation.y = 0.25;
        group.add(ring); this.disposables.push(rg, rm);
      }
      this.scene.add(group);
      this.planets.push({ name: planetName(rng), pos, radius: R, group, body, spin: rr(rng, 0.01, 0.05), mat, color: pal.cols[3] });
    });
  }
  private buildStation() {
    const g = this.station; const D = this.disposables;
    const hull = new THREE.MeshStandardMaterial({ color: 0xb8c0d8, metalness: 0.6, roughness: 0.35 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x3a3f58, metalness: 0.5, roughness: 0.6 });
    const glow = new THREE.MeshBasicMaterial({ color: 0x7ff6ff });
    const panel = new THREE.MeshStandardMaterial({ color: 0x1b2f7a, emissive: 0x0a1a55, metalness: 0.3, roughness: 0.4 });
    D.push(hull, dark, glow, panel);
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, p: [number, number, number], r: [number, number, number] = [0, 0, 0], parent: THREE.Object3D = g) => {
      const mesh = new THREE.Mesh(geo, m); mesh.position.set(...p); mesh.rotation.set(...r); parent.add(mesh); D.push(geo); return mesh;
    };
    add(new THREE.CylinderGeometry(5, 5, 34, 20), hull, [0, 0, 0]);
    add(new THREE.SphereGeometry(8, 24, 16), dark, [0, 0, 0]);
    add(new THREE.CylinderGeometry(9, 6, 5, 20), hull, [0, 18, 0]);
    add(new THREE.ConeGeometry(2, 10, 8), dark, [0, 25, 0]);
    this.ring = new THREE.Group(); g.add(this.ring);
    add(new THREE.TorusGeometry(26, 2.6, 12, 48), hull, [0, 0, 0], [Math.PI / 2, 0, 0], this.ring);
    add(new THREE.TorusGeometry(26, 0.5, 6, 64), glow, [0, 1.6, 0], [Math.PI / 2, 0, 0], this.ring);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2;
      add(new THREE.BoxGeometry(26, 1.2, 1.2), dark, [Math.cos(a) * 13, 0, Math.sin(a) * 13], [0, -a, 0], this.ring);
    }
    for (const s of [-1, 1]) {
      add(new THREE.BoxGeometry(30, 0.4, 9), panel, [s * 22, -12, 0]);
      add(new THREE.BoxGeometry(14, 0.8, 0.8), dark, [s * 7, -12, 0]);
    }
    const bg = new THREE.SphereGeometry(0.9, 8, 6); D.push(bg);
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const m = new THREE.Mesh(bg, new THREE.MeshBasicMaterial({ color: i % 2 ? 0xff4466 : 0x66ff99 }));
      D.push(m.material as THREE.Material);
      m.position.set(Math.cos(a) * 29, 0, Math.sin(a) * 29); this.ring.add(m); this.beacons.push(m);
    }
    const gt = glowTexture('rgba(160,255,255,1)', 'rgba(60,200,255,0.3)'); D.push(gt);
    const sm = new THREE.SpriteMaterial({ map: gt, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.8 }); D.push(sm);
    const halo = new THREE.Sprite(sm); halo.scale.setScalar(70); g.add(halo);
    const pl = new THREE.PointLight(0x66e0ff, 2.2 * LIGHT_K, 160, 2); pl.position.set(0, 10, 0); g.add(pl);
    g.position.copy(this.stationPos); g.rotation.z = 0.12;
    this.scene.add(g);
  }
  update(dt: number, t: number, cam: THREE.Camera, focus: THREE.Vector3) {
    this.sky.position.copy(cam.position);
    this.stars.position.copy(cam.position);
    (this.stars.material as THREE.ShaderMaterial).uniforms.uTime.value = t;
    this.sun.position.copy(cam.position).addScaledVector(this.sunDir, 3000);
    this.sunLight.position.copy(focus).addScaledVector(this.sunDir, 200);
    this.sunLight.target.position.copy(focus);
    for (const p of this.planets) { p.body.rotation.y += p.spin * dt; }
    this.ring.rotation.y += dt * 0.25;
    this.beacons.forEach((b, i) => { b.visible = Math.sin(t * 4 + i) > -0.2; });
  }
  setStarScale(s: number) { (this.stars.material as THREE.ShaderMaterial).uniforms.uScale.value = s; }
  dispose() {
    this.disposables.forEach(d => d.dispose());
    this.rt.dispose();
  }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}
// r170 activa la gestión de color por defecto; r128 no la tiene. La desactivamos
// para que THREE.Color('#hex') se comporte igual en ambas versiones.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

import * as THREE from 'three';
import { glowTexture } from './shaders';

export interface Bolt { mesh: THREE.Mesh; vel: THREE.Vector3; life: number; enemy: boolean; dmg: number; alive: boolean }

const MAX = 90;
const _q = new THREE.Quaternion(); const _z = new THREE.Vector3(0, 0, 1);

/** Pool de proyectiles láser (jugador y piratas). */
export class Bolts {
  list: Bolt[] = [];
  private geo = new THREE.BoxGeometry(0.5, 0.5, 10);
  private glowGeo = new THREE.BoxGeometry(1.8, 1.8, 13);
  private mats = {
    p: new THREE.MeshBasicMaterial({ color: 0x9ffcff }), pg: new THREE.MeshBasicMaterial({ color: 0x1fa8ff, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false }),
    e: new THREE.MeshBasicMaterial({ color: 0xffb0a0 }), eg: new THREE.MeshBasicMaterial({ color: 0xff2a4a, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false }),
  };
  private tex = glowTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0.35)');
  private spr = { p: new THREE.SpriteMaterial({ map: this.tex, color: 0x5ae8ff, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }),
    e: new THREE.SpriteMaterial({ map: this.tex, color: 0xff3a5a, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }) };
  constructor(private scene: THREE.Scene) {
    for (let i = 0; i < MAX; i++) {
      const mesh = new THREE.Mesh(this.geo, this.mats.p);
      mesh.add(new THREE.Mesh(this.glowGeo, this.mats.pg));
      const s = new THREE.Sprite(this.spr.p); s.scale.setScalar(7); s.position.z = 4; mesh.add(s);
      mesh.visible = false; scene.add(mesh);
      this.list.push({ mesh, vel: new THREE.Vector3(), life: 0, enemy: false, dmg: 0, alive: false });
    }
  }
  fire(pos: THREE.Vector3, dir: THREE.Vector3, speed: number, enemy: boolean, dmg: number, inherit?: THREE.Vector3) {
    const b = this.list.find(x => !x.alive); if (!b) return;
    b.alive = true; b.enemy = enemy; b.dmg = dmg; b.life = enemy ? 2.2 : 1.4;
    b.vel.copy(dir).multiplyScalar(speed); if (inherit) b.vel.add(inherit);
    b.mesh.position.copy(pos); b.mesh.visible = true;
    _q.setFromUnitVectors(_z, dir); b.mesh.quaternion.copy(_q);
    b.mesh.material = enemy ? this.mats.e : this.mats.p;
    (b.mesh.children[0] as THREE.Mesh).material = enemy ? this.mats.eg : this.mats.pg;
    (b.mesh.children[1] as THREE.Sprite).material = enemy ? this.spr.e : this.spr.p;
  }
  update(dt: number) {
    for (const b of this.list) {
      if (!b.alive) continue;
      b.life -= dt;
      if (b.life <= 0) { this.kill(b); continue; }
      b.mesh.position.addScaledVector(b.vel, dt);
    }
  }
  kill(b: Bolt) { b.alive = false; b.mesh.visible = false; }
  clear() { this.list.forEach(b => this.kill(b)); }
  dispose() {
    this.list.forEach(b => this.scene.remove(b.mesh));
    this.geo.dispose(); this.glowGeo.dispose(); Object.values(this.mats).forEach(m => m.dispose());
    this.spr.p.dispose(); this.spr.e.dispose(); this.tex.dispose();
  }
}

